require_role('admin');$tab=(string)($_GET['tab']??'users');if(!in_array($tab,['users','teams','categories'],true))$tab='users';admin_page_start('People & categories','Manage accounts, maintenance teams and issue categories.');admin_tabs('users',['users'=>'Users','teams'=>'Maintenance teams','categories'=>'Categories'],$tab);
if($tab==='categories'):$category_rows=q('SELECT c.*,(SELECT COUNT(*) FROM issues i WHERE i.category_id=c.id) report_count FROM categories c ORDER BY c.active DESC,c.name')->fetchAll();?><section class="panel"><h2>Issue categories</h2><p class="small muted">Archived categories remain on existing reports and in report filters. Rename changes the displayed label on existing reports; the old and new names are recorded in the audit log.</p><div class="table-wrap"><table><thead><tr><th>Category</th><th>Availability</th><th>Reports</th><th>Manage</th></tr></thead><tbody><?php foreach($category_rows as $c):?><tr><td><?=e($c['name'])?></td><td><?=badge($c['active']?'Active':'Archived')?></td><td><?=(int)$c['report_count']?></td><td><details class="admin-row-menu"><summary>Edit category</summary><form method="post"><?php csrf();?><input type="hidden" name="action" value="category_rename"><input type="hidden" name="category_id" value="<?=$c['id']?>"><input type="hidden" name="previous_name" value="<?=e($c['name'])?>"><input type="hidden" name="previous_active" value="<?=(int)$c['active']?>"><label>Category name<input name="name" minlength="2" maxlength="80" value="<?=e($c['name'])?>" required></label><button class="button secondary">Save name</button></form><form method="post" data-confirm="<?=$c['active']?'Archive this category for new reports? Existing reports remain available.':'Restore this category for new reports?'?>"><?php csrf();?><input type="hidden" name="action" value="category_access"><input type="hidden" name="category_id" value="<?=$c['id']?>"><input type="hidden" name="previous_name" value="<?=e($c['name'])?>"><input type="hidden" name="previous_active" value="<?=(int)$c['active']?>"><button class="text-button"><?=$c['active']?'Archive category':'Restore category'?></button></form></details></td></tr><?php endforeach;?></tbody></table></div><form method="post" class="admin-inline-create"><?php csrf();?><input type="hidden" name="action" value="category"><label>New category<input name="name" minlength="2" maxlength="80" required></label><button class="button secondary">Add category</button></form></section><?php admin_page_end();return;endif;
$search=trim(substr((string)($_GET['search']??''),0,160));$role=(string)($_GET['role']??'');$access=(string)($_GET['access']??'');$w=['1=1'];$p=[];if($tab==='teams')$w[]="role='maintenance'";elseif(in_array($role,['citizen','officer','admin','maintenance'],true)){$w[]='role=?';$p[]=$role;}if(in_array($access,['0','1'],true)){$w[]='active=?';$p[]=(int)$access;}if($search!==''){$w[]='(name LIKE ? OR email LIKE ?)';$p[]='%'.$search.'%';$p[]='%'.$search.'%';}$where=' WHERE '.implode(' AND ',$w);$total=(int)q('SELECT COUNT(*) FROM users'.$where,$p)->fetchColumn();$max=max(1,(int)ceil($total/20));$pn=min($max,max(1,(int)($_GET['p']??1)));$rows=q('SELECT * FROM users'.$where.' ORDER BY id DESC LIMIT 20 OFFSET '.(($pn-1)*20),$p)->fetchAll();
?><div class="admin-section-heading"><h2><?=$tab==='teams'?'Maintenance teams':'Registered users'?> <small><?=$total?></small></h2><div class="row"><a class="button" href="index.php?page=routing&amp;tab=accounts">＋ Add scoped staff account</a><a class="text-link" href="#add-account">Add citizen / System Admin</a></div></div><form method="get" class="panel admin-filter-grid"><input type="hidden" name="page" value="users"><input type="hidden" name="tab" value="<?=e($tab)?>"><label class="admin-search">Search name or email<input type="search" name="search" maxlength="160" value="<?=e($search)?>"></label><?php if($tab!=='teams'):?><label>Role<select name="role"><option value="">All roles</option><?php foreach(['citizen','officer','maintenance','admin'] as $v):?><option <?=$role===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><?php endif;?><label>Access<select name="access"><option value="">All accounts</option><option value="1" <?=$access==='1'?'selected':''?>>Active</option><option value="0" <?=$access==='0'?'selected':''?>>Disabled</option></select></label><div class="admin-filter-actions"><button class="button secondary">Search</button><a class="text-link" href="index.php?page=users&amp;tab=<?=e($tab)?>">Reset</a></div></form>
<section class="panel no-pad"><?php if(!$rows):?><div class="admin-empty"><h3>No accounts match</h3><p>Reset the filters or add an account below.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Access</th><?php if($tab==='teams'):?><th>Open workload</th><?php endif;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e(admin_account_scope($u))?></td><td><?=badge($u['active']?'Active':'Disabled')?></td><?php if($tab==='teams'):?><td><?=(int)q("SELECT COUNT(*) FROM issues WHERE maintenance_id=? AND status NOT IN ('Resolved','Rejected','Duplicate')",[$u['id']])->fetchColumn()?> open</td><?php endif;?><td><details class="admin-row-menu"><summary>Manage</summary><a class="text-link" href="index.php?page=oversight&amp;tab=account&amp;id=<?=(int)$u['id']?>">Account details →</a><form method="post"><?php csrf();?><input type="hidden" name="action" value="admin_edit_user"><input type="hidden" name="user_id" value="<?=$u['id']?>"><label>Display name<input name="name" minlength="2" maxlength="100" value="<?=e($u['name'])?>" required></label><button class="button secondary">Save name</button></form><?php if($u['role']==='maintenance'&&$u['active']):?><a class="text-link" href="index.php?page=routing&amp;tab=accounts&amp;mapping=town&amp;user_id=<?=$u['id']?>">Configure team town →</a><?php endif;if($u['role']!=='admin'):?><a class="text-link" href="index.php?page=system&amp;tab=recovery&amp;email=<?=e(rawurlencode($u['email']))?>">Account recovery →</a><form method="post" data-confirm="Change access for this account? Open officer/team work must be reassigned before disabling."><?php csrf();?><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="user_id" value="<?=$u['id']?>"><button class="text-button"><?=$u['active']?'Disable':'Enable'?></button></form><?php endif;?></details></td></tr><?php endforeach;?></tbody></table></div><?php endif;admin_pager($pn,$max,$total);?></section>
<section class="panel section-space" id="add-account"><details class="admin-add-account" <?=($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='create_user')?'open':''?>><summary>Add a citizen / System Admin account</summary><form method="post"><?php csrf();?><input type="hidden" name="action" value="create_user"><div class="admin-filter-grid"><label>Full name / team name<input name="name" minlength="2" maxlength="100" value="<?=e($_POST['name']??'')?>" required></label><label>Email<input type="email" name="email" maxlength="190" value="<?=e($_POST['email']??'')?>" required></label><label>Temporary password<div class="password-control"><input id="new-account-password" type="password" name="password" minlength="10" maxlength="72" autocomplete="new-password" required><button type="button" data-password-toggle="new-account-password" aria-pressed="false">Show</button></div></label><label>Role<select name="role"><?php foreach(['citizen'=>'Citizen','admin'=>'System Admin'] as $key=>$label):?><option value="<?=$key?>" <?=((string)($_POST['role']??($tab==='teams'?'maintenance':'officer'))===$key)?'selected':''?>><?=$label?></option><?php endforeach;?></select></label></div><button class="button">Create user</button><p class="small muted">For Province Admin, District Officer and Maintenance Team accounts, use Add scoped staff account above. Give credentials privately and ask the account holder to change the temporary password in My profile.</p></form></details></section><?php admin_page_end();
